package com.smartmart.ai.service;
import com.smartmart.ai.dto.AiRequest; import com.smartmart.analytics.service.AnalyticsService; import com.smartmart.intelligence.service.InventoryIntelligenceService; import com.smartmart.inventory.service.InventoryService; import com.smartmart.product.repository.ProductRepository; import com.smartmart.recommendation.service.RecommendationService; import com.smartmart.user.entity.User; import com.smartmart.wishlist.service.WishlistService; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import java.util.*; import java.util.stream.Collectors;
@Service @RequiredArgsConstructor public class AiAssistantService { private final InventoryService inventory; private final WishlistService wishlist; private final RecommendationService recommendations; private final InventoryIntelligenceService intelligence; private final AnalyticsService analytics; private final ProductRepository products; private final AiProvider provider;
 public String shopper(User user,AiRequest request){String q=request.getMessage().toLowerCase();String context=shopperContext(user);if(provider.isConfigured())return provider.answer(context,request.getMessage()); if(q.contains("wishlist")){var items=wishlist.list(user);return items.isEmpty()?"Your wishlist is empty.":items.stream().map(x->x.getName()+": "+status(x.getAvailabilityStatus(),x.getAvailableQuantity(),x.getDiscountPercentage(),x.getAisle(),x.getShelf())).collect(Collectors.joining("\n"));}if(q.contains("recommend")){var items=recommendations.forUser(user);return items.isEmpty()?"There are no available recommendations yet. Add wishlist items or complete an order to improve them.":"Recommendations based on your orders, wishlist, offers, and availability:\n"+items.stream().map(x->x.getName()+" — "+x.getAvailableQuantity()+" available").collect(Collectors.joining("\n"));}if(q.contains("discount"))return inventory.discounted().isEmpty()?"There are no active discounts right now.":inventory.discounted().stream().map(x->x.getProductName()+" — "+x.getDiscountPercentage()+"% off").collect(Collectors.joining("\n"));return productAnswer(q,"I can check your wishlist, recommendations, live availability, aisle locations, and active discounts."); }
 public String manager(AiRequest request){String q=request.getMessage().toLowerCase();String context=managerContext();if(provider.isConfigured())return provider.answer(context,request.getMessage());if(q.contains("expir")){return intelligence.expiryInsights().stream().filter(x->!"SAFE".equals(x.getStatus())).map(x->x.getProductName()+": "+x.getQuantity()+" units, "+x.getDaysUntilExpiry()+" days, "+x.getRecommendedAction()).collect(Collectors.joining("\n"));}if(q.contains("reorder")||q.contains("run out")||q.contains("stock")){return intelligence.reorderRecommendations().stream().map(x->x.getProductName()+": "+x.getCurrentStock()+" in stock; "+x.getRiskLevel()+" risk; suggested reorder "+x.getSuggestedReorderQuantity()+" units.").collect(Collectors.joining("\n"));}var d=analytics.dashboard();return "Today’s data-backed overview: "+d.get("lowStockProducts")+" low-stock products, "+d.get("expiringInventory")+" expiring inventory records, "+d.get("totalOrders")+" orders, and revenue of "+d.get("revenue")+"."; }
 private String productAnswer(String q,String fallback){var matches=products.findAll().stream().filter(p->q.contains(p.getName().toLowerCase())||q.contains(p.getBrand().toLowerCase())).toList();if(matches.isEmpty())return fallback;return matches.stream().map(p->{var i=inventory.product(p.getId());return p.getName()+": "+i.getQuantity()+" available"+(p.getAisle()==null?"":" in Aisle "+p.getAisle()+", Shelf "+p.getShelf())+(i.getDiscountPercentage()!=null&&i.getDiscountPercentage().signum()>0?", "+i.getDiscountPercentage()+"% off":"");}).collect(Collectors.joining("\n"));}
 private String shopperContext(User u){return "Wishlist: "+wishlist.list(u)+". Recommendations: "+recommendations.forUser(u);}
 private String managerContext(){return "Analytics: "+analytics.dashboard()+". Stock risks: "+intelligence.stockOutRisks()+". Expiry: "+intelligence.expiryInsights();}
 private String status(String state,Integer qty,java.math.BigDecimal discount,String aisle,String shelf){return state+" ("+qty+" available)"+(discount!=null&&discount.signum()>0?", "+discount+"% off":"")+(aisle!=null?", Aisle "+aisle+", Shelf "+shelf:"");}
}
